import { useEffect, useState } from "react";

// Close-ups of the onigiri under its slide: pre-rendered stills (public/shots/onigiri-*.webp), no 3D at runtime.
//  - "port": from underneath, cable unplugged, up the channel at the JTAG-8 socket;
//  - "screen": straight down on the OLED showing the firmware's main menu.
// Regenerated by scripts/capture-static.mjs, which opens the page with ?shots=live (dev only).

export type OnigiriShot = "port" | "screen";
const LIVE = import.meta.env.DEV && new URLSearchParams(location.search).get("shots") === "live";

/** A close-up of the onigiri with a caption under it. */
export default function OnigiriRender({ shot, caption }: { shot: OnigiriShot; caption: string }) {
  const key = `onigiri-${shot}`;
  const [url, setUrl] = useState<string | null>(LIVE ? null : `shots/${key}.webp`);

  // Dev only: render the still live and publish it for the capture script.
  useEffect(() => {
    if (!LIVE) return;
    let cancelled = false;
    import("./shotsLive").then(({ enqueueShot, renderOnigiri }) => enqueueShot(() => renderOnigiri(shot)))
      .then((u) => {
        if (cancelled) return;
        ((window as unknown as { __shots: Record<string, unknown> }).__shots ??= {})[key] = { url: u };
        setUrl(u);
      })
      .catch(() => undefined);
    return () => { cancelled = true; };
  }, [key, shot]);

  return (
    <figure className="select-none">
      <div className="relative w-full overflow-hidden rounded-lg border bg-foreground/[0.03]" style={{ aspectRatio: "480 / 360" }}>
        {url && <img src={url} alt="" draggable={false} loading="lazy" decoding="async" className="absolute inset-0 w-full h-full" />}
      </div>
      <figcaption className="mt-2 font-mono text-xs md:text-sm text-muted-foreground">{caption}</figcaption>
    </figure>
  );
}
